import React, {useEffect, useState } from 'react';
import { useNavigate } from "react-router-dom";
import './inventory.css';
// import { getProducts } from '../data/dataFetching';


function Inventory( { getProducts, updateProduct, addProduct, getSuppliers, deleteProduct } ) {

    
    const [suppliers, setSuppliers] = useState([]);
    const navigate = useNavigate();
    const [products, setProducts] = useState([]);
             
    useEffect(() => {
      getSuppliers().then(data => setSuppliers(data));
      getProducts().then(data => setProducts(data));
    }, [getProducts, getSuppliers]);

    let [search, setSearch] = useState("")
    let [sort, setSort] = useState("name")

    function onSearchChange(e) {
        setSearch(e.target.value)
    }

    function onSortChange(e) {
        setSort(e.target.value)
    }

    function getSortedProductsData() {
        return products.filter((item) => {
            return item.name.toLowerCase().includes(search.toLowerCase())
        }).sort((a, b) => {
            return (a[sort] + "").localeCompare(b[sort] + "")
        })
    }


    return (
        <>
        
        <h1>Inventory</h1>

        <div className="tableFunctions">

            <div className="tableSeachbar">
                <i class="bi bi-search"></i>
                <input class="tableSeachInput" type="text" placeholder="Search" onChange={onSearchChange} value={search}></input>
            </div>

            
            <div className="sortWithAddFunctions">
                {/* Filter dropdown */}
                <select className="tableSort" onChange={onSortChange} value={sort}>
                    <option value="id">Product ID</option>
                    <option value="name">Name</option>
                    <option value="category">Category</option>
                </select>

                {/* Add Product button */}
                <button className="addBtn" onClick={() => navigate("/inventory/add-product")}>
                    Add Product
                </button>
            </div>

        </div>

        <div className="table-container">
            <table>
                <thead>
                    <tr>
                        <th>ProductID</th>
                        <th>Image</th>
                        <th>Name</th>
                        <th>Category</th>
                        <th>Quantity</th>
                        <th>Unit</th>
                        <th>Supplier</th>
                        
                    </tr>
                </thead>

                <tbody>
                    {products.length > 0 &&
                        getSortedProductsData().map((item) => {
                            return <tr>
                                <td>{item.id}</td>
                                <td><span className={item.product_picture}></span></td>
                                <td><a href={ "/inventory/product-details/" + item.id}>{item.name}</a></td>
                                <td>{item.category}</td>
                                <td>{item.quantity}</td>
                                <td>{item.unit}</td>
                                <td><a href={ "/suppliers/info/" +item.supplier_id}>{suppliers.find(supplier => supplier.id === item.supplier_id)?.name}</a></td>
                            </tr>
                        })
                    }
                </tbody>
            </table>

        </div>


        </>
    )
}

export default Inventory;
